    "content": "from __future__ import annotations

from decimal import Decimal, InvalidOperation
from typing import Mapping

from .round_div import round_div


def convert_currency(cents: int, source: str, target: str, rates: Mapping[str, str]) -> int:
    if source not in rates:
        raise ValueError(f"Source currency '{source}' not found in rates")
    if target not in rates:
        raise ValueError(f"Target currency '{target}' not found in rates")
    if source == target:
        return cents
    source_rate_str = rates[source]
    target_rate_str = rates[target]
    try:
        source_rate = Decimal(source_rate_str)
        target_rate = Decimal(target_rate_str)
    except InvalidOperation:
        raise ValueError("Invalid rate format")
    if source_rate <= 0:
        raise ValueError(f"Source rate must be positive")
    if target_rate <= 0:
        raise ValueError(f"Target rate must be positive")
    st = source_rate.as_tuple()
    tt = target_rate.as_tuple()
    sd = -st.exponent if st.exponent < 0 else 0
    td = -tt.exponent if tt.exponent < 0 else 0
    mx = max(sd, td)
    sc = 10 ** mx
    ss = int(source_rate * sc)
    ts = int(target_rate * sc)
    num = cents * ts
    den = ss
    return round_div(num, den, mode="half_even")
"
